#include "LocalMultiplayer.h"
#include "RuntimeUI.h"
#include <cstdio>
#include <algorithm>
#include <limits>
int checks=0,failures=0;void Check(bool x,const char* s){++checks;failures+=!x;std::printf("%s %s\n",x?"PASS":"FAIL",s);}
int main(){InputDeviceHub hub;LocalPlayers players;std::string error;InputMap map;map.Add("go",false);map.AddBinding("go",{"key:W"});map.AddBinding("go",{"key:Up"});map.AddBinding("go",{"pad:South"});map.Add("ui_click",false);map.AddBinding("ui_click",{"mouse:Left"});map.Add("ui_activate",false);map.AddBinding("ui_activate",{"pad:South"});map.Add("pause",false);map.AddBinding("pause",{"pad:Start"});
 auto a=players.Create("A",map,error)->id,b=players.Create("B",map,error)->id;
 Check(a!=b,"identities separate from devices/entities");Check(players.Find(a)->devices.empty()&&!players.Find(a)->entity,"unassigned player starts neutral");
 Check(players.Assign(a,hub,{"keyboard",{"key:W"}},error)&&players.Assign(b,hub,{"keyboard",{"key:Up"}},error),"one aggregate keyboard partitions disjoint keys");
 Check(!players.Assign(b,hub,{"keyboard",{"key:W"}},error)&&players.Find(b)->devices[0].controls.count("key:Up"),"conflict rejects transaction without losing prior assignment");
 hub.BeginFrame();players.Route(hub);hub.BeginFrame();hub.Set("keyboard","key:W",1);hub.Set("keyboard","key:W",0);players.Route(hub);players.BeginFixedStep();
 Check(players.Find(a)->input.FixedAction("go").pressed&&players.Find(a)->input.FixedAction("go").released&&!players.Find(b)->input.FixedAction("go").pressed,"tap edges stay independent and survive same-frame release");players.BeginFixedStep();Check(!players.Find(a)->input.FixedAction("go").pressed,"catch-up fixed step cannot repeat edge");
 auto pad1=hub.Connect("gamepad","One"),pad2=hub.Connect("gamepad","Two");Check(pad1!=pad2,"two identical controller names have distinct tokens");
 players.Assign(a,hub,{pad1,{}, {0,0,1,1}},error);players.Assign(b,hub,{pad2,{}, {0,0,1,1}},error);hub.BeginFrame();players.Route(hub);hub.BeginFrame();hub.Set(pad1,"pad:South",1);players.Route(hub);players.BeginFixedStep();Check(players.Find(a)->input.FixedAction("go").pressed&&!players.Find(b)->input.FixedAction("go").pressed,"controller input cannot leak to another player");
 Check(!players.Assign(b,hub,{pad1,{}, {0,0,1,1}},error),"controller exclusive ownership");hub.Disconnect(pad1);hub.BeginFrame();players.Route(hub);Check(!players.Find(a)->input.Action("go").held,"disconnect cancels held controller state");auto replacement=hub.Connect("gamepad","One");Check(replacement!=pad1&&!players.Assign(a,hub,{pad1,{}, {0,0,1,1}},error),"reconnect cannot alias stale controller token");
 players.Unassign(b,pad2);hub.Set(pad2,"pad:South",1);players.Assign(a,hub,{pad2,{}, {0,0,1,1}},error);hub.BeginFrame();players.Route(hub);Check(players.Find(a)->input.Action("go").held&&!players.Find(a)->input.Action("go").pressed,"reassignment baselines held input without phantom press");
 Check(players.Assign(a,hub,{"touch",{},{0,0,.5f,1}},error)&&players.Assign(b,hub,{"touch",{},{.5f,0,.5f,1}},error),"touch device partitions regions");Check(!players.Assign(b,hub,{"touch",{},{.4f,0,.6f,1}},error),"overlapping touch ownership rejects");
 hub.BeginFrame();players.Route(hub);hub.BeginFrame();hub.Touches({{100,.2f,.4f,1},{101,.8f,.4f,1}});players.Route(hub);auto id=players.Find(a)->input.Touches()[0].id;Check(players.Find(a)->input.Touches().size()==1&&players.Find(b)->input.Touches().size()==1,"two simultaneous fingers route independently");
 hub.BeginFrame();hub.Touches({{100,.9f,.4f,1},{101,.1f,.4f,1}});players.Route(hub);Check(players.Find(a)->input.Touches()[0].id==id&&players.Find(a)->input.Touches()[0].x==.9f,"captured touch crosses viewports without reassignment or ID churn");
 hub.BeginFrame();hub.Touches({});players.Route(hub);Check(players.Find(a)->input.Touches().empty()&&!players.Find(a)->input.Action("ui_click").held,"release clears actual per-player contact");
 hub.BeginFrame();hub.RecordTouch({102,.2f,.4f,1},true);hub.RecordTouch({102,.2f,.4f,0},false);players.Route(hub);Check(players.Find(a)->input.Action("ui_click").pressed&&players.Find(a)->input.Action("ui_click").released,"sub-frame touch click retains both edges");
 hub.Reset();hub.BeginFrame();players.Route(hub);Check(players.Find(a)->input.Touches().empty()&&!players.Find(a)->input.Pointer().down,"background/reset clears devices and player observations");
 Check(!players.SetViewport(a,{0,0,0,1},error)&&!players.SetViewport(a,{0,0,std::numeric_limits<float>::quiet_NaN(),1},error),"invalid viewports reject without partial publication");
 SceneTransform pose;Check(players.SetView(a,pose,70,.1f,100,error)&&players.HasViews(),"independent view is optional");Check(!players.SetView(b,pose,70,10,1,error),"invalid view range rejects");
 RuntimeUI ui;UIDocument doc;doc.reference={100,100};UIElement root;root.id="root";root.kind=UIKind::Canvas;UIElement button;button.id="button";button.parent="root";button.kind=UIKind::Button;button.size={100,100};doc.elements={root,button};doc.modal=true;
 auto da=ui.Add(doc,"a",0,error),db=ui.Add(doc,"b",0,error);ui.SetPlayer(da,a);ui.SetPlayer(db,b);ui.PlayerViewport(a,{0,0,.5f,1});ui.PlayerViewport(b,{.5f,0,.5f,1});ui.Layout(200,100);
 Check(!ui.Paused()&&ui.Paused(a)&&ui.Paused(b),"local modal does not pause the shared world");Check(ui.LayoutOf(da,"button")->rect.position.x==0&&ui.LayoutOf(db,"button")->rect.position.x==100,"HUD layout clips to independent viewport");
 InputSystem ia,ib;ia.SetMap(map,error);ib.SetMap(map,error);ia.SetPhysical("pad:South",1);ui.Input(ia,{0,0},false,200,100,a);auto events=ui.TakeEvents();bool clickA=false,clickB=false;for(auto& e:events){clickA|=e.type=="click"&&e.player==a;clickB|=e.type=="click"&&e.player==b;}Check(clickA&&!clickB,"only owning player navigates/activates its UI");
 const auto stale=a;ui.RemovePlayer(a);players.Remove(a);Check(!players.Find(stale)&&ui.Find("a")==0&&players.Find(b),"leaving removes identity/HUD without deleting other player");auto fresh=players.Create("new",map,error)->id;Check(fresh!=stale,"new player cannot revive a stale identity");
 // Several sources assigned to one identity must compose levels: releasing a
 // second pad/touch must not cancel a still-held first pad/physical mouse.
 InputDeviceHub combinedHub;LocalPlayers combined;auto cp=combined.Create("combined sources",map,error)->id;auto ca=combinedHub.Connect("gamepad","A"),cb=combinedHub.Connect("gamepad","B");combined.Assign(cp,combinedHub,{ca,{}, {0,0,1,1}},error);combined.Assign(cp,combinedHub,{cb,{}, {0,0,1,1}},error);combined.Assign(cp,combinedHub,{"mouse",{}, {0,0,1,1}},error);combined.Assign(cp,combinedHub,{"touch",{}, {0,0,1,1}},error);auto tick=[&](){combinedHub.BeginFrame();};tick();combined.Route(combinedHub);tick();combinedHub.Set(ca,"pad:South",1);combined.Route(combinedHub);Check(combined.Find(cp)->input.Action("go").held,"first assigned source supplies held button");tick();combinedHub.Set(cb,"pad:South",1);combined.Route(combinedHub);tick();combinedHub.Set(cb,"pad:South",0);combined.Route(combinedHub);Check(combined.Find(cp)->input.Action("go").held&&!combined.Find(cp)->input.Action("go").released,"releasing second controller cannot cancel first controller's held action");tick();combinedHub.Set(ca,"pad:South",0);combined.Route(combinedHub);Check(!combined.Find(cp)->input.Action("go").held&&combined.Find(cp)->input.Action("go").released,"last held source release publishes actual release");tick();combinedHub.Set("mouse","mouse:Left",1);combinedHub.Pointer("mouse",{.2f,.4f,true});combined.Route(combinedHub);tick();combinedHub.RecordTouch({500,.2f,.4f,1},true);combinedHub.RecordTouch({500,.2f,.4f,0},false);combined.Route(combinedHub);Check(combined.Find(cp)->input.Action("ui_click").held&&!combined.Find(cp)->input.Action("ui_click").released,"touch tap cannot cancel same player's held physical mouse");
 tick();combinedHub.Set("mouse","mouse:Left",0);combinedHub.Pointer("mouse",{0,0,false});combined.Route(combinedHub);tick();combinedHub.RecordTouch({501,.5f,.5f,1},true);combinedHub.RecordTouch({501,.5f,.5f,0},false);combined.Route(combinedHub);auto touchPointer=combined.Find(cp)->input.Pointer();Check(touchPointer.x==.5f&&touchPointer.y==.5f&&!touchPointer.down,"touch release retains its actual position before UI dispatch");UIDocument tapDoc=doc;tapDoc.elements[1].offset={40,40};tapDoc.elements[1].size={20,20};RuntimeUI tapUI;auto td=tapUI.Add(tapDoc,"touch-release",0,error);tapUI.SetPlayer(td,cp);tapUI.Input(combined.Find(cp)->input,{touchPointer.x*100,touchPointer.y*100},true,100,100,cp);auto tapped=tapUI.TakeEvents();Check(std::any_of(tapped.begin(),tapped.end(),[&](const auto& e){return e.type=="click"&&e.player==cp;}),"touch release uses its actual UI position even with an assigned idle physical mouse");
 Check(LocalPlayers::ViewSize({0,0,1,1},8000,4000)==glm::ivec2(2048,1024),"view resolution cap preserves actual projection aspect");
 LocalPlayers bounded;for(int i=0;i<8;i++)bounded.Create("bounded",map,error);Check(!bounded.Create("ninth",map,error)&&bounded.All().size()==8,"player capacity rejects without replacing identities");LocalPlayers names;Check(!names.Create(std::string(129,'x'),map,error)&&names.All().empty(),"oversized identity name rejects before publication");
 InputDeviceHub overflow;LocalPlayers overflowPlayers;auto overflowId=overflowPlayers.Create("bounded transitions",map,error)->id;overflowPlayers.Assign(overflowId,overflow,{"keyboard",{"key:W"}},error);overflow.BeginFrame();overflowPlayers.Route(overflow);overflow.BeginFrame();for(int i=0;i<4100;i++)overflow.Set("keyboard","key:W",i%2);overflowPlayers.Route(overflow);overflowPlayers.BeginFixedStep();Check(overflow.overflow&&!overflowPlayers.Find(overflowId)->input.FixedAction("go").pressed&&!overflowPlayers.Find(overflowId)->input.FixedAction("go").held,"bounded raw overflow cancels instead of inventing actions");
 std::printf("%d checks %d failures\n",checks,failures);return failures?1:0;}
